input.command:
mkdir -p /tmp/shim && cat > /tmp/shim/shim.c <<'EOF'
#define _GNU_SOURCE
#include <stdio.h>
#include <unistd.h>
#include <dlfcn.h>
#include <sys/uio.h>
#include <poll.h>

static FILE *lg(void){ static FILE*f; if(!f){ f=fopen("/tmp/shim/log.txt","a"); } return f; }

ssize_t read(int fd, void *b, size_t n){
  static ssize_t (*real)(int,void*,size_t);
  if(!real) real = dlsym(RTLD_NEXT,"read");
  ssize_t r = real(fd,b,n);
  fprintf(lg(),"read(fd=%d, n=%zu) = %zd\n", fd, n, r); fflush(lg());
  return r;
}
ssize_t readv(int fd, const struct iovec *v, int c){
  static ssize_t (*real)(int,const struct iovec*,int);
  if(!real) real = dlsym(RTLD_NEXT,"readv");
  ssize_t r = real(fd,v,c);
  fprintf(lg(),"readv(fd=%d) = %zd\n", fd, r); fflush(lg());
  return r;
}
ssize_t pread(int fd, void *b, size_t n, off_t o){
  static ssize_t (*real)(int,void*,size_t,off_t);
  if(!real) real = dlsym(RTLD_NEXT,"pread");
  ssize_t r = real(fd,b,n,o);
  fprintf(lg(),"pread(fd=%d,n=%zu) = %zd\n", fd, n, r); fflush(lg());
  return r;
}
int poll(struct pollfd *f, nfds_t n, int t){
  static int (*real)(struct pollfd*,nfds_t,int);
  if(!real) real = dlsym(RTLD_NEXT,"poll");
  int r = real(f,n,t);
  fprintf(lg(),"poll(nfds=%lu,timeout=%d) = %d\n",(unsigned long)n,t,r); fflush(lg());
  return r;
}
EOF
gcc -shared -fPIC -o /tmp/shim/shim.so /tmp/shim/shim.c -ldl 2>&1 && echo "BUILD OK"
